import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`sec-insider`,heroTitle:`Track SEC filings and insider trades in minutes`,heroSubtitle:`Perplexity Computer monitors SEC Form 4 filings, scores insider signals, and delivers morning alerts — automatically.`,heroCta:`Track tickers`,inputUrlCta:`Track tickers`,inputUrlPlaceholder:`e.g. NVDA, AAPL, TSLA...`,inputUrlPrefill:`Go to {url} and extract the list of stock tickers. For each ticker, monitor SEC EDGAR for Form 4 insider filings daily. For each filing detected: 1) Extract transaction details — insider name, title, transaction type (buy/sell), shares traded, price, and total value. 2) Score the signal strength based on insider role, transaction size relative to holdings, cluster buying patterns, and historical accuracy of that insider's trades. 3) Research recent analyst coverage and sentiment for context. 4) Deliver a formatted morning alert summarizing all new insider transactions, ranked by signal strength, with historical insider trading patterns for each company and relevant analyst commentary.`,heroOverlaySteps:[`Parsing your ticker list and validating each symbol against SEC EDGAR`,`Scanning recent Form 4 filings for insider buy and sell transactions`,`Scoring signal strength based on insider role, size, and historical accuracy`,`Transaction details, pattern analysis, and analyst context — ready to review`],generatingSteps:[`Visiting {url} to extract and validate your ticker watchlist`,`Designing an agent to monitor SEC EDGAR for Form 4 filings daily`,`Configuring signal scoring based on insider role, trade size, and cluster patterns`,`Setting up morning alerts with transaction summaries, patterns, and analyst context`],featureSectionTitle:`From tickers to insider signals`,featureCardTitles:[`Connects to your investing stack`,`Outputs you can trade on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Slack, Google Sheets, Notion — Computer plugs into your tools so filings, alerts, and analysis flow into one workflow.`,`Daily insider transaction summaries. Signal strength scores. Historical pattern analysis. Analyst context briefs. Computer delivers research you can act on every morning.`],capabilitySectionTitle:`Your analyst desk, on autopilot`,capabilitySectionSubtitle:`Enter your tickers, step away, get morning insider alerts.`,capabilityCards:[{title:`Filing Detection`,description:`Computer can monitor SEC EDGAR for new Form 4 filings across your watchlist — catching insider buys and sells.`},{title:`Signal Scoring`,description:`Computer can score each insider transaction by role seniority, trade size relative to holdings, cluster activity, and that insider's historical accuracy.`},{title:`Pattern Analysis`,description:`Computer can surface historical insider trading patterns for each company — identifying whether current activity matches prior setups that preceded moves.`},{title:`Connect Your Tools`,description:`Computer can send alerts to Gmail, Slack, Google Sheets, and Notion — build workflows that deliver insider signals wherever you work.`},{title:`Remember & Learn`,description:`Computer can remember your watchlist, scoring preferences, and alert thresholds across sessions — so every scan builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch for unusual insider activity daily and flag high-conviction signals — set up alerts that ping you before the market opens.`}]});export{t as default};
